                      <text x="${cx}" y="${cy + 50}" text-anchor="middle" font-size="9" fill="${isOk ? '#4ade80' : '#f87171'}">● ${pr.status || '—'} • ${lat != null ? lat + 'ms RTT' : '—'}</text>
